@namespace Components

<div class="checkout-wizard">
    @switch (_currentStep)
    {
        case Step.Shipping:
            <ShippingStep ShippingInfo="_order.Shipping"
                          OnNext="HandleShippingComplete" />
            break;

        case Step.Payment:
            <PaymentStep PaymentInfo="_order.Payment"
                         OnBack="HandleBackToShipping"
                         OnPlaceOrder="HandlePlaceOrder" />
            break;
    }
</div>

@code {
    private enum Step { Shipping, Payment }

    private Step _currentStep = Step.Shipping;
    private readonly Order _order = new();

    [Parameter]
    public EventCallback<Order> OnOrderPlaced { get; set; }

    private void HandleShippingComplete()
    {
        _currentStep = Step.Payment;
    }

    private void HandleBackToShipping()
    {
        _currentStep = Step.Shipping;
    }

    private async Task HandlePlaceOrder()
    {
        await OnOrderPlaced.InvokeAsync(_order);
    }
}

@namespace Components
@implements IDisposable
@inject IAddressValidator AddressValidator

<div class="shipping-step">
    <h3>Shipping Information</h3>

    <label>
        Name
        <input @bind="ShippingInfo.Name" disabled="@_isValidating" />
    </label>

    <label>
        Address
        <input @bind="ShippingInfo.Address" disabled="@_isValidating" />
    </label>

    <label>
        City
        <input @bind="ShippingInfo.City" disabled="@_isValidating" />
    </label>

    <label>
        Zip Code
        <input @bind="ShippingInfo.ZipCode" disabled="@_isValidating" />
    </label>

    @if (!string.IsNullOrEmpty(_errorMessage))
    {
        <div class="validation-error">@_errorMessage</div>
    }

    <button disabled="@_isValidating" @onclick="HandleNext">
        @if (_isValidating)
        {
            <span class="loading-indicator">Validating…</span>
        }
        else
        {
            <span>Next</span>
        }
    </button>
</div>

@code {
    private CancellationTokenSource? _cts;
    private bool _isValidating;
    private string? _errorMessage;

    [Parameter]
    public ShippingInfo ShippingInfo { get; set; } = new();

    [Parameter]
    public EventCallback OnNext { get; set; }

    private async Task HandleNext()
    {
        _errorMessage = null;

        // Cancel any in-flight validation
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = new CancellationTokenSource();
        var token = _cts.Token;

        _isValidating = true;

        try
        {
            var isValid = await AddressValidator.ValidateAddressAsync(
                ShippingInfo.Address,
                ShippingInfo.City,
                ShippingInfo.ZipCode,
                token);

            token.ThrowIfCancellationRequested();

            if (isValid)
            {
                await OnNext.InvokeAsync();
            }
            else
            {
                _errorMessage = "The address could not be validated. Please check and try again.";
            }
        }
        catch (OperationCanceledException)
        {
            // Validation was cancelled — no action needed
        }
        finally
        {
            _isValidating = false;
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

